Q: How to get TextInput Value with useRef? A: <pre><code>const inputRef = useRef(null);
 &lt;TextInput
     ref={inputRef}
     value={'test'}
     editable={false}
     style={styles.InputStyle}
     // Add These lines
     onChangeText={value =&gt; {
            // can be called anywhere to set value
            inputRef.current.value = value
          }}

 /&gt;



console.log(inputRef.current.value)  ---&gt;  now gives textinput valueeee
</code></pre>
